CREATE FUNCTION pg_temp.plan_of(q text) RETURNS text AS $$ DECLARE r text; t text := ''; BEGIN FOR r IN EXECUTE 'EXPLAIN ' || q LOOP t := t || r || E'\n'; END LOOP; RETURN t; END $$ LANGUAGE plpgsql;
SELECT x.idx, x.method, x.is_unique, x.key_cols, (pg_temp.plan_of('SELECT * FROM person_discounts WHERE person_id = 1 AND pizzeria_id = 1') LIKE '%idx_person_discounts_unique%') AS used_in_plan FROM (SELECT 1) d LEFT JOIN (SELECT c.relname AS idx, am.amname AS method, i.indisunique AS is_unique, (SELECT string_agg(pg_get_indexdef(i.indexrelid, n, true), ', ' ORDER BY n) FROM generate_series(1, i.indnkeyatts) n) AS key_cols FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid JOIN pg_am am ON am.oid = c.relam WHERE c.relname = 'idx_person_discounts_unique' AND c.relnamespace = current_schema()::regnamespace) x ON true
